+function autoDetectOrg(projectRoot: string): string | null {
+  const orgsDir = join(projectRoot, 'orgs');
+  if (!existsSync(orgsDir)) return null;
+  try {
+    const orgs = readdirSync(orgsDir, { withFileTypes: true })
